import{_ as s,a0 as o,w as p,s as l,ao as b,I as a,x as u,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——安裝Ubuntu後做什麼 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——安裝Ubuntu後做什麼 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——安裝Ubuntu後做什麼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——安裝Ubuntu後做什麼 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips–Things To Do After Installing Ubuntu","title":"每日Ubuntu小技巧——安裝Ubuntu後做什麼","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips–Things To Do After Installing Ubuntu.md","filePath":"[post].md"}'),r={name:"201310/Daily Ubuntu Tips–Things To Do After Installing Ubuntu.md"};function d(U,t,T,g,m,f){const n=o("Link");return p(),l("div",null,[t[11]||(t[11]=b('<h1 id="每日ubuntu小技巧——安裝ubuntu後做什麼" tabindex="-1">每日Ubuntu小技巧——安裝Ubuntu後做什麼 <a class="header-anchor" href="#每日ubuntu小技巧——安裝ubuntu後做什麼" aria-label="Permalink to “每日Ubuntu小技巧——安裝Ubuntu後做什麼”">​</a></h1><p>許多Windows用户開始使用Ubuntu時都感到束手無策。Ubuntu與Windows截然不同，想要輕鬆駕馭Ubuntu可不是一件簡單的事情。Ubuntu的使用方式不同於Windows。許多用户對命令列、文件系統的佈局和應用程序的名稱都感到陌生。但是不用擔心，我們會提供幫助的。</p><p>如果你以前是Windows或者Mac OS X用户現在想學Ubuntu，那你來對地方了。我們正努力幫助新用户開始Ubuntu之旅。我們的口號理所當然就是“<strong>菜鳥教程</strong>”。</p><p>我們的教程大多不是針對專業人士的，而是面向剛開始學習Windows和Ubuntu的新手。所以，在Ubuntu上遇到了任何困擾，都可以回來轉轉。</p><p>好了，言歸正傳。幾天前一個讀者問了我們一個問題，如下：</p><blockquote><p>安裝好Ubuntu後首先要做什麼？</p></blockquote><p>很簡單，第一次安裝Ubuntu時，你可能有很多事情想做。但是最重要的是讓它正常工作。不要擔心遇到難題，這些你很快就會明白。</p><p>這裏有一些安裝好Ubuntu之後你最初想要做的事。可能你想做的比這還多，但這些是比較重要的。</p><ul><li><p>更新系統 －首先更新你的系統。系統更新可以讓你安裝比較新的軟件包和一些其它程序的修正。使用Ubuntu時你可以使用下面的命令正確地進行系統更新。</p><p>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade &amp;&amp; sudo apt-get autoremove</p></li><li><p>安裝好Ubuntu後要做的另外一件事就是運行下面的命令。這條命令能幫助你安裝編解碼器和因法律原因而排除在Ubuntu外的軟件包。Ubuntu並未預裝這些比較重要的程序。而沒有這些程序你可能無法聽音樂、看電影或者做其它的事情。所以，如果你安裝了Ubuntu但是不能播放DVD或者聽音樂CD，那就運行下面的命令吧。</p><p>sudo apt-get install ubuntu-restricted-extras</p></li></ul><p>以上這些命令並非你將在Ubuntu運行的全部的命令，但它們是安裝好Ubuntu後你首先要運行的。希望這些能幫助到你。</p><p>使用愉快！</p><hr>',12)),a("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tipsthings-to-do-after-installing-ubuntu/"},{default:i(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2013/10/daily-ubuntu-tipsthings-to-do-after-installing-ubuntu/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=u("譯者：",-1)),e(n,{href:"https://github.com/Linchenguang"},{default:i(()=>[...t[2]||(t[2]=[u("Linchenguang",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[3]||(t[3]=[u("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const _=s(r,[["render",d]]);export{w as __pageData,_ as default};
